api.look('agent');
const cx = api.w/2, top = 150, W = 300, H = 520;
const k = api.seg(t, 0, 1.2);
api.rect(cx-W/2, top, W, H, {r:36, c:'fg', w:4, k});
api.text('Settings', cx, top+50, {size:34, weight:'bold', align:'center', k:api.seg(t,0.8,1.6)});
const rows = ['Account','Notifications','Log out','Help','Privacy'];
rows.forEach((r,i)=>{
  const kk = api.stag(t, i, {gap:0.2, dur:0.4, from:1.0});
  const y = top+120+i*70;
  api.line(cx-W/2+24, y+30, cx+W/2-24, y+30, {c:'line', w:2, k:kk});
  api.text(r, cx-W/2+30, y, {size:22, c:(r==='Log out'?'bad':(r==='Help'?'a2':'fg')), k:kk});
});
api.say('Settings, before today', 0.3, 3.3);

api.look('agent');
const cx = api.w/2, top = 150, W = 300, H = 520, L = cx-W/2+30;
const rows = ['Account','Notifications','Privacy'];
api.rect(cx-W/2, top, W, H, {r:36, c:'fg', w:4});
api.text('Settings', cx, top+50, {size:34, weight:'bold', align:'center'});
const m = api.ease(api.seg(t, 1.5, 3.5));
rows.forEach((r,i)=>{
  const y = top+120+i*70;
  api.line(L-6, y+30, cx+W/2-24, y+30, {c:'line', w:2});
  api.text(r, L, y, {size:22});
});
// Log out slides from row 3 (y=top+260) to the bottom (y=top+440)
const ly = api.lerp(top+260, top+440, m);
api.line(L-6, ly+30, cx+W/2-24, ly+30, {c:'line', w:2});
api.rect(L-12, ly-10, W-36, 50, {r:14, c:'bad', w:3, a:0.9});
api.text('Log out', L, ly, {size:22, c:'bad', weight:'bold'});
api.arrow(cx+W/2-40, top+270, cx+W/2-40, top+430, {c:'accent', w:4, k:api.seg(t,0.6,1.8)});
api.label('Moved to bottom', cx, top+H+40, {k:api.seg(t,3,4)});
api.say('Log out moved to the bottom', 0.3, 5.2);

api.look('agent');
const cx = api.w/2, top = 150, W = 300, H = 520, L = cx-W/2+30;
api.rect(cx-W/2, top, W, H, {r:36, c:'fg', w:4});
api.text('Settings', cx, top+50, {size:34, weight:'bold', align:'center'});
['Account','Notifications','Privacy'].forEach((r,i)=>{
  const y = top+120+i*70;
  api.line(L-6, y+30, cx+W/2-24, y+30, {c:'line', w:2});
  api.text(r, L, y, {size:22});
});
const ky = top+330, kk = api.seg(t, 0.4, 1.4);
api.highlight(L-12, ky-10, W-36, 56, {k:kk, c:'good'});
api.text('Dark mode', L, ky, {size:22, weight:'bold', k:kk});
// switch flips on
const on = api.ease(api.seg(t, 2.5, 3.2));
const sx = cx+W/2-90;
api.rect(sx, ky, 56, 30, {r:15, c:'fg', w:3, fill:on>0.5?'good':'panel', k:kk});
api.circle(sx+15+on*26, ky+15, 11, {c:'fg', fill:'ink', w:2, k:kk});
api.shape('moon', sx+28, ky-26, 30, {c:'a3', k:api.seg(t,3.2,4.2)});
api.scribble(cx, ky+18, W/2-10, 40, {k:api.seg(t,3.8,5)});
api.label('New: Dark mode', cx, top+H+40, {k:api.seg(t,1.2,2.2)});
api.say('A Dark mode switch was added', 0.3, 5.8);

api.look('agent');
const cx = api.w/2, top = 150, W = 300, H = 520, L = cx-W/2+30;
api.rect(cx-W/2, top, W, H, {r:36, c:'fg', w:4});
api.text('Settings', cx, top+50, {size:34, weight:'bold', align:'center'});
['Account','Notifications','Privacy'].forEach((r,i)=>{
  const y = top+120+i*70;
  api.line(L-6, y+30, cx+W/2-24, y+30, {c:'line', w:2});
  api.text(r, L, y, {size:22});
});
const y = top+400;
const gone = api.ease(api.seg(t, 1.2, 2.8));
api.text('Help', L+gone*40, y, {size:22, c:'a2', a:1-gone});
api.line(L-6, y+30, cx+W/2-24, y+30, {c:'line', w:2, a:1-gone});
api.shape('cross', cx+W/2-60, y+10, 36, {c:'bad', k:api.seg(t,0.4,1.2)});
api.line(L-6, y+12, L+70, y+12, {c:'bad', w:4, k:api.seg(t,0.4,1.2)});
api.label('Removed: Help', cx, top+H+40, {k:api.seg(t,2.2,3.2)});
api.say('The Help row was removed', 0.3, 4.7);

api.look('agent');
const cx = api.w/2;
const items = [
  {s:'arrow', t:'Log out', d:'moved down', c:'accent'},
  {s:'moon', t:'Dark mode', d:'added', c:'good'},
  {s:'cross', t:'Help', d:'removed', c:'bad'}
];
items.forEach((it,i)=>{
  const kk = api.stag(t, i, {gap:1.2, dur:0.8, from:0.3});
  const y = 200+i*170;
  api.circle(cx-100, y, 46, {c:it.c, w:4, k:kk});
  api.shape(it.s, cx-100, y, 44, {c:it.c, k:kk});
  api.text(it.t, cx-30, y-26, {size:30, weight:'bold', k:kk});
  api.text(it.d, cx-30, y+10, {size:22, c:it.c, k:kk});
});
api.say('Three changes to Settings', 0.3, 5.7);
